     1→/**
     2→ * FKSolicitudDesembolsoRequest - Solicitud de Desembolso contract request form for Operations department
     3→ * Specialized form with PDF upload, data extraction, and dynamic Anexo I table
     4→ */
     5→import React, { useState, useEffect } from 'react';
     6→import {
     7→  Box,
     8→  TextField,
     9→  Button,
    10→  Card,
    11→  CardContent,
    12→  Typography,
    13→  Alert,
    14→  CircularProgress,
    15→  Divider,
    16→  Table,
    17→  TableBody,
    18→  TableCell,
    19→  TableContainer,
    20→  TableHead,
    21→  TableRow,
    22→  IconButton,
    23→  Paper,
    24→  Stack,
    25→} from '@mui/material';
    26→import {
    27→  Search as SearchIcon,
    28→  UploadFile as UploadFileIcon,
    29→  Add as AddIcon,
    30→  Delete as DeleteIcon,
    31→  CheckCircle as CheckCircleIcon,
    32→} from '@mui/icons-material';
    33→import { legalService } from '../../services/legalService';
    34→import { operationsService } from '../../services/operationsService';
    35→import type { Client, ContractGeneration, AnexoItem, CotizacionData } from '../../types/legal';
    36→
    37→const FKSolicitudDesembolsoRequest: React.FC = () => {
    38→  // Client search state
    39→  const [searchQuery, setSearchQuery] = useState('');
    40→  const [searching, setSearching] = useState(false);
    41→  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
    42→  const [searchResults, setSearchResults] = useState<Client[]>([]);
    43→
    44→  // Cotización PDF state
    45→  const [cotizacionFile, setCotizacionFile] = useState<File | null>(null);
    46→  const [extractedData, setExtractedData] = useState<CotizacionData | null>(null);
    47→  const [extracting, setExtracting] = useState(false);
    48→  const [fileError, setFileError] = useState<string | null>(null);
    49→
    50→  // Form state
    51→  const [numeroCotizacion, setNumeroCotizacion] = useState('');
    52→  const [fechaContrato, setFechaContrato] = useState('');
    53→  const [diasPlazo, setDiasPlazo] = useState(120);
    54→  const [anexoItems, setAnexoItems] = useState<AnexoItem[]>([]);
    55→  const [montoTotal, setMontoTotal] = useState(0);
    56→
    57→  // Submission state
    58→  const [requesting, setRequesting] = useState(false);
    59→  const [requestedContract, setRequestedContract] = useState<ContractGeneration | null>(null);
    60→  const [error, setError] = useState<string | null>(null);
    61→
    62→  // Calculate total when anexo items change
    63→  useEffect(() => {
    64→    const total = anexoItems.reduce((sum, item) => sum + (item.monto || 0), 0);
    65→    setMontoTotal(total);
    66→  }, [anexoItems]);
    67→
    68→  const handleSearch = async () => {
    69→    setSearching(true);
    70→    setError(null);
    71→    setSearchResults([]);
    72→    setSelectedClient(null);
    73→
    74→    try {
    75→      const results = await legalService.searchClients({ query: searchQuery.trim() || undefined });
    76→      setSearchResults(results);
    77→
    78→      if (results.length === 0) {
    79→        setError('No se encontraron clientes con ese criterio de búsqueda');
    80→      } else if (results.length === 1) {
    81→        setSelectedClient(results[0]);
    82→      }
    83→    } catch (err) {
    84→      setError('Error al buscar clientes. Por favor intente nuevamente.');
    85→      console.error('Search error:', err);
    86→    } finally {
    87→      setSearching(false);
    88→    }
    89→  };
    90→
    91→  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    92→    const file = event.target.files?.[0];
    93→    if (!file) return;
    94→
    95→    if (file.type !== 'application/pdf') {
    96→      setFileError('Solo se permiten archivos PDF');
    97→      setCotizacionFile(null);
    98→      return;
    99→    }
   100→
   101→    if (file.size > 5 * 1024 * 1024) {
   102→      setFileError('El archivo no debe superar 5MB');
   103→      setCotizacionFile(null);
   104→      return;
   105→    }
   106→
   107→    setCotizacionFile(file);
   108→    setFileError(null);
   109→    // Reset extracted data when new file is uploaded
   110→    setExtractedData(null);
   111→  };
   112→
   113→  const handleExtractData = async () => {
   114→    if (!cotizacionFile) {
   115→      setError('Debe seleccionar un archivo PDF primero');
   116→      return;
   117→    }
   118→
   119→    setExtracting(true);
   120→    setError(null);
   121→
   122→    try {
   123→      const data = await operationsService.parseCotizacionPdf(cotizacionFile);
   124→      setExtractedData(data);
   125→
   126→      // Pre-populate form fields
   127→      setNumeroCotizacion(data.numeroCotizacion || '');
   128→      setFechaContrato(data.fechaContratCredito || '');
   129→      setAnexoItems(data.anexoItems || []);
   130→
   131→      setError(null);
   132→    } catch (err) {
   133→      const error = err as { response?: { data?: { detail?: string } }; message?: string };
   134→      setError(`Error al extraer datos del PDF: ${error.response?.data?.detail || error.message || 'Error desconocido'}`);
   135→      console.error('Extract error:', err);
   136→    } finally {
   137→      setExtracting(false);
   138→    }
   139→  };
   140→
   141→  const handleAddAnexoRow = () => {
   142→    setAnexoItems([...anexoItems, { acreedor: '', numeroInstrumento: '', monto: 0 }]);
   143→  };
   144→
   145→  const handleRemoveAnexoRow = (index: number) => {
   146→    setAnexoItems(anexoItems.filter((_, i) => i !== index));
   147→  };
   148→
   149→  const handleAnexoItemChange = (index: number, field: keyof AnexoItem, value: string | number) => {
   150→    const updated = [...anexoItems];
   151→    updated[index] = { ...updated[index], [field]: value };
   152→    setAnexoItems(updated);
   153→  };
   154→
   155→  const handleSubmit = async () => {
   156→    if (!selectedClient) {
   157→      setError('Por favor seleccione un cliente');
   158→      return;
   159→    }
   160→
   161→    if (!numeroCotizacion) {
   162→      setError('Número de cotización es requerido');
   163→      return;
   164→    }
   165→
   166→    if (!fechaContrato) {
   167→      setError('Fecha de contrato de crédito es requerida');
   168→      return;
   169→    }
   170→
   171→    if (anexoItems.length === 0) {
   172→      setError('Debe agregar al menos un ítem en el Anexo I');
   173→      return;
   174→    }
   175→
   176→    if (montoTotal <= 0) {
   177→      setError('El monto total debe ser mayor a 0');
   178→      return;
   179→    }
   180→
   181→    setRequesting(true);
   182→    setError(null);
   183→
   184→    try {
   185→      // Convert anexo items to backend format (snake_case) - note that frontend uses camelCase
   186→      const anexoItemsBackend: AnexoItem[] = anexoItems.map(item => ({
   187→        acreedor: item.acreedor,
   188→        numeroInstrumento: item.numeroInstrumento,
   189→        monto: item.monto,
   190→      }));
   191→
   192→      const request: any = {
   193→        client_nit: selectedClient.nit,
   194→        numero_cotizacion_desembolso: numeroCotizacion,
   195→        fecha_contrato_credito: fechaContrato,
   196→        monto: montoTotal,
   197→        dias_plazo: diasPlazo,
   198→        anexo_items: anexoItemsBackend,
   199→      };
   200→
   201→      const contract = await operationsService.generateSolicitudDesembolso(request);
   202→      setRequestedContract(contract);
   203→      setError(null);
   204→    } catch (err) {
   205→      const error = err as { response?: { data?: { detail?: string } }; message?: string };
   206→      setError(`Error al generar solicitud: ${error.response?.data?.detail || error.message || 'Error desconocido'}`);
   207→      console.error('Generation error:', err);
   208→    } finally {
   209→      setRequesting(false);
   210→    }
   211→  };
   212→
   213→  const handleReset = () => {
   214→    setSearchQuery('');
   215→    setSelectedClient(null);
   216→    setSearchResults([]);
   217→    setCotizacionFile(null);
   218→    setExtractedData(null);
   219→    setNumeroCotizacion('');
   220→    setFechaContrato('');
   221→    setDiasPlazo(120);
   222→    setAnexoItems([]);
   223→    setRequestedContract(null);
   224→    setError(null);
   225→    setFileError(null);
   226→  };
   227→
   228→  if (requestedContract) {
   229→    return (
   230→      <Card>
   231→        <CardContent>
   232→          <Box display="flex" alignItems="center" mb={2}>
   233→            <CheckCircleIcon color="success" sx={{ fontSize: 48, mr: 2 }} />
   234→            <Box>
   235→              <Typography variant="h6" gutterBottom>
   236→                Solicitud de Desembolso Generada Exitosamente
   237→              </Typography>
   238→              <Typography variant="body2" color="text.secondary">
   239→                La solicitud ha sido enviada al departamento Legal para revisión
   240→              </Typography>
   241→            </Box>
   242→          </Box>
   243→
   244→          <Divider sx={{ my: 2 }} />
   245→
   246→          <Stack spacing={2}>
   247→            <Box>
   248→              <Typography variant="subtitle2" color="text.secondary">ID de Contrato</Typography>
   249→              <Typography variant="body1" fontWeight="medium">{requestedContract.contract_id}</Typography>
   250→            </Box>
   251→            <Box>
   252→              <Typography variant="subtitle2" color="text.secondary">Cliente</Typography>
   253→              <Typography variant="body1">{selectedClient?.nombre_importador}</Typography>
   254→            </Box>
   255→            <Box>
   256→              <Typography variant="subtitle2" color="text.secondary">Número de Cotización</Typography>
   257→              <Typography variant="body1">{numeroCotizacion}</Typography>
   258→            </Box>
   259→            <Box>
   260→              <Typography variant="subtitle2" color="text.secondary">Monto Total</Typography>
   261→              <Typography variant="body1">${montoTotal.toLocaleString()} COP</Typography>
   262→            </Box>
   263→            <Box>
   264→              <Typography variant="subtitle2" color="text.secondary">Estado</Typography>
   265→              <Typography variant="body1" color="warning.main">En Revisión</Typography>
   266→            </Box>
   267→          </Stack>
   268→
   269→          <Box mt={3}>
   270→            <Button variant="contained" onClick={handleReset} fullWidth>
   271→              Generar Nueva Solicitud
   272→            </Button>
   273→          </Box>
   274→        </CardContent>
   275→      </Card>
   276→    );
   277→  }
   278→
   279→  return (
   280→    <Box>
   281→      <Typography variant="h6" gutterBottom>
   282→        Solicitud de Desembolso
   283→      </Typography>
   284→
   285→      {error && (
   286→        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
   287→          {error}
   288→        </Alert>
   289→      )}
   290→
   291→      {/* Section 1: Client Search */}
   292→      <Card sx={{ mb: 2 }}>
   293→        <CardContent>
   294→          <Typography variant="subtitle1" gutterBottom fontWeight="medium">
   295→            1. Seleccionar Cliente
   296→          </Typography>
   297→
   298→          <Stack direction="row" spacing={2} alignItems="center">
   299→            <TextField
   300→              fullWidth
   301→              label="Buscar por NIT o Nombre"
   302→              value={searchQuery}
   303→              onChange={(e) => setSearchQuery(e.target.value)}
   304→              onKeyPress={(e) => e.key === 'Enter' && handleSearch()}
   305→              disabled={searching}
   306→              size="small"
   307→            />
   308→            <Button
   309→              variant="contained"
   310→              onClick={handleSearch}
   311→              disabled={searching || !searchQuery.trim()}
   312→              startIcon={searching ? <CircularProgress size={20} /> : <SearchIcon />}
   313→              sx={{ minWidth: 120 }}
   314→            >
   315→              Buscar
   316→            </Button>
   317→          </Stack>
   318→
   319→          {searchResults.length > 1 && (
   320→            <Box mt={2}>
   321→              <Typography variant="body2" color="text.secondary" gutterBottom>
   322→                Resultados de búsqueda:
   323→              </Typography>
   324→              {searchResults.map((client) => (
   325→                <Card
   326→                  key={client.id}
   327→                  variant="outlined"
   328→                  sx={{
   329→                    mb: 1,
   330→                    cursor: 'pointer',
   331→                    '&:hover': { bgcolor: 'action.hover' },
   332→                    bgcolor: selectedClient?.id === client.id ? 'action.selected' : 'inherit',
   333→                  }}
   334→                  onClick={() => setSelectedClient(client)}
   335→                >
   336→                  <CardContent sx={{ py: 1 }}>
   337→                    <Typography variant="body1" fontWeight="medium">
   338→                      {client.nombre_importador}
   339→                    </Typography>
   340→                    <Typography variant="body2" color="text.secondary">
   341→                      NIT: {client.nit} | {client.ciudad_domicilio}
   342→                    </Typography>
   343→                  </CardContent>
   344→                </Card>
   345→              ))}
   346→            </Box>
   347→          )}
   348→
   349→          {selectedClient && (
   350→            <Box mt={2} p={2} bgcolor="success.lighter" borderRadius={1}>
   351→              <Typography variant="body2" color="success.dark" fontWeight="medium">
   352→                Cliente seleccionado: {selectedClient.nombre_importador} (NIT: {selectedClient.nit})
   353→              </Typography>
   354→            </Box>
   355→          )}
   356→        </CardContent>
   357→      </Card>
   358→
   359→      {/* Section 2: Cotización Upload */}
   360→      <Card sx={{ mb: 2 }}>
   361→        <CardContent>
   362→          <Typography variant="subtitle1" gutterBottom fontWeight="medium">
   363→            2. Cargar Cotización PDF
   364→          </Typography>
   365→
   366→          <input
   367→            type="file"
   368→            accept="application/pdf"
   369→            onChange={handleFileChange}
   370→            style={{ display: 'none' }}
   371→            id="cotizacion-upload"
   372→          />
   373→          <label htmlFor="cotizacion-upload">
   374→            <Button variant="outlined" component="span" startIcon={<UploadFileIcon />} fullWidth>
   375→              {cotizacionFile ? cotizacionFile.name : 'Seleccionar Archivo PDF'}
   376→            </Button>
   377→          </label>
   378→
   379→          {fileError && (
   380→            <Alert severity="error" sx={{ mt: 1 }}>
   381→              {fileError}
   382→            </Alert>
   383→          )}
   384→
   385→          {cotizacionFile && !extractedData && (
   386→            <Box mt={2}>
   387→              <Button
   388→                variant="contained"
   389→                onClick={handleExtractData}
   390→                disabled={extracting}
   391→                startIcon={extracting ? <CircularProgress size={20} /> : <UploadFileIcon />}
   392→                fullWidth
   393→              >
   394→                {extracting ? 'Extrayendo Datos...' : 'Extraer Datos del PDF'}
   395→              </Button>
   396→            </Box>
   397→          )}
   398→
   399→          {extractedData && (
   400→            <Alert severity="success" sx={{ mt: 2 }}>
   401→              Datos extraídos exitosamente: {extractedData.anexoItems.length} ítems encontrados
   402→            </Alert>
   403→          )}
   404→        </CardContent>
   405→      </Card>
   406→
   407→      {/* Section 3: Extracted Data (Editable) */}
   408→      {extractedData && (
   409→        <Card sx={{ mb: 2 }}>
   410→          <CardContent>
   411→            <Typography variant="subtitle1" gutterBottom fontWeight="medium">
   412→              3. Datos de la Solicitud
   413→            </Typography>
   414→
   415→            <Stack spacing={2}>
   416→              <TextField
   417→                fullWidth
   418→                label="Número de Cotización de Desembolso"
   419→                value={numeroCotizacion}
   420→                onChange={(e) => setNumeroCotizacion(e.target.value)}
   421→                required
   422→                size="small"
   423→              />
   424→              <TextField
   425→                fullWidth
